"""One-shot parser process. Paths are generated by the API, never from filenames."""
import io
import resource
import sys
from pathlib import Path

MAX_PAGES = 300
MAX_OUTPUT = 25 * 1024 * 1024
FORBIDDEN = {'/OpenAction', '/AA', '/A', '/JS', '/JavaScript', '/EmbeddedFiles',
             '/EF', '/AcroForm', '/XFA', '/RichMedia', '/Annots', '/Launch'}


class MergeError(ValueError):
    """Fixed, safe-to-display validation error."""


def merge(paths: list[Path]) -> bytes:
    from pypdf import PdfReader, PdfWriter
    from pypdf.generic import DictionaryObject, ArrayObject, IndirectObject
    writer = PdfWriter()
    total = 0
    for path in paths:
        reader = PdfReader(path, strict=True)
        if reader.is_encrypted:
            raise MergeError('Encrypted PDFs are not supported.')
        seen = set()
        budget = [0]

        def inspect(obj, depth=0):
            budget[0] += 1
            if depth > 80 or budget[0] > 100000:
                raise MergeError('PDF object graph exceeds limits.')
            if isinstance(obj, IndirectObject):
                key = (obj.idnum, obj.generation)
                if key in seen:
                    return
                seen.add(key)
                inspect(obj.get_object(), depth + 1)
            elif isinstance(obj, DictionaryObject):
                if FORBIDDEN.intersection(obj):
                    raise MergeError('Interactive PDFs, actions and attachments are not supported.')
                for value in obj.values():
                    inspect(value, depth + 1)
            elif isinstance(obj, ArrayObject):
                for value in obj:
                    inspect(value, depth + 1)

        inspect(reader.trailer)
        count = len(reader.pages)
        total += count
        if not count or total > MAX_PAGES:
            raise MergeError('Use 1–300 total pages.')
        for page in reader.pages:
            writer.add_page(page)
    writer.add_metadata({'/Producer': 'VAILABLE'})
    output = io.BytesIO()
    writer.write(output)
    if output.tell() > MAX_OUTPUT:
        raise MergeError('Merged output exceeds 25 MiB.')
    return output.getvalue()


def main():
    resource.setrlimit(resource.RLIMIT_AS, (512 * 1024**2,) * 2)
    resource.setrlimit(resource.RLIMIT_CPU, (8, 8))
    resource.setrlimit(resource.RLIMIT_FSIZE, (MAX_OUTPUT,) * 2)
    resource.setrlimit(resource.RLIMIT_NOFILE, (64, 64))
    try:
        result = merge([Path(p) for p in sys.argv[1:]])
    except MergeError as error:
        sys.stdout.buffer.write(str(error).encode())
        return 2
    except Exception:
        sys.stdout.buffer.write(b'Invalid or unsupported PDF.')
        return 2
    sys.stdout.buffer.write(result)
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
